"""Sandbox stub for BKN capabilities, generated by Context Loader.

_configure(event) injects credentials and lifecycle context before execution.
"""

import json
import os
import pathlib
import re
import sys
import urllib.request

_CFG = {}
_SESSION = {}
_TRACE_GAPS = set()
_TRACE_DIAGNOSTIC_PREFIX = "[BKN_TRACE]"
_TRACE_GAP_REASON = re.compile(r"^trace_call_unrecorded:[A-Za-z0-9_-]{1,64}:[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$")

# 最近几次调用返回值的形状。脚本抛异常时随 traceback 一并打出——代码模式下调用方
# 必须先写出取值路径再执行，猜错时 traceback 只说 "NoneType is not iterable"，不说
# 真实结构，于是整整一轮被用来 print 原始数据找字段名，而那又把数据灌回了上下文，
# 正好抵消代码模式省上下文的意义。这里只记形状不记值。
_SHAPES = []
_SHAPE_LIMIT = 6

# /workspace is shared by all calls. Create and enter a conversation-specific
# subdirectory so scripts can use relative paths without crossing sessions.
WORKDIR = pathlib.Path("/workspace")

# The MCP endpoint is in-cluster. A inherited proxy would make urllib issue an
# absolute-form request that the gateway rejects, so disable proxies explicitly.
_OPENER = urllib.request.build_opener(urllib.request.ProxyHandler({}))


class ToolError(RuntimeError):
    """A tool invocation failed; message contains the server response."""


def _configure(event):
    """Inject MCP endpoint, credentials, and lifecycle context; prepare workdir."""
    _install_shape_hook()
    global WORKDIR
    _CFG.update(event)
    _SESSION.clear()
    _TRACE_GAPS.clear()

    # Use an ASCII-only normalization instead of a hash. run_shell must derive
    # the same directory outside this stub, and Python's isalnum accepts Unicode
    # while the Go implementation intentionally does not.
    _SAFE = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"
    conversation = str((event.get("bkn") or {}).get("conversation_id") or "").strip()
    safe = "".join(c if c in _SAFE else "-" for c in conversation)[:64]
    scope = event.get("workspace_scope")
    if scope is not None:
        if not isinstance(scope, str) or not scope or any(c not in _SAFE for c in scope):
            raise ValueError("invalid sandbox workspace scope")
    else:
        # Legacy direct toolkit execution has no server session scope. Isolate
        # this invocation rather than expose a shared directory.
        import uuid
        scope = "conv-" + safe if safe else "adhoc-" + uuid.uuid4().hex
    candidate = pathlib.Path("/workspace") / scope
    try:
        candidate.mkdir(parents=True, exist_ok=True)
        os.chdir(candidate)
        WORKDIR = candidate
    except OSError as error:
        raise RuntimeError("cannot prepare isolated sandbox workspace") from error


def _rpc(method, params=None, notify=False):
    body = {"jsonrpc": "2.0", "method": method}
    if params is not None:
        body["params"] = params
    if not notify:
        body["id"] = _SESSION.get("seq", 0) + 1
        _SESSION["seq"] = body["id"]
    headers = {
    "Content-Type": "application/json",
    "Accept": "application/json, text/event-stream",
    "Accept-Language": _CFG.get("locale", "zh-CN"),
    "Authorization": "Bearer " + _CFG["token"],
    }
    if _SESSION.get("id"):
        headers["Mcp-Session-Id"] = _SESSION["id"]
    request = urllib.request.Request(
        _CFG["mcp"], data=json.dumps(body).encode(),
        headers=headers, method="POST",
    )
    with _OPENER.open(request, timeout=_CFG.get("timeout", 120)) as response:
        if not _SESSION.get("id"):
            _SESSION["id"] = response.headers.get("Mcp-Session-Id")
        # JSON-RPC notifications deliberately have no response payload. Some
        # Streamable HTTP servers keep the accepted SSE channel open, so do not
        # wait for a body that the protocol will never send.
        if notify:
            return None
        if "text/event-stream" in response.headers.get("Content-Type", "").lower():
            # Streamable HTTP is allowed to keep the SSE connection open after
            # delivering the JSON-RPC response. Read one complete event instead
            # of waiting for EOF and consuming the whole run_code timeout.
            data = []
            while True:
                raw_line = response.readline()
                if not raw_line:
                    break
                line = raw_line.decode().rstrip("\r\n")
                if line == "":
                    if data:
                        return json.loads("\n".join(data))
                    continue
                if line.startswith("data:"):
                    data.append(line[5:].lstrip())
            return json.loads("\n".join(data)) if data else None
        raw = response.read().decode()
        return json.loads(raw) if raw.strip() else None


def _ensure_session():
    """Reuse one MCP session per execution and initialize it at most once."""
    if _SESSION.get("ready"):
        return
    _rpc("initialize", {
        "protocolVersion": "2025-06-18",
        "capabilities": {},
        "clientInfo": {"name": "bkn-sandbox", "version": "1"},
    })
    _rpc("notifications/initialized", {}, notify=True)
    _SESSION["ready"] = True


def _observe_trace_gaps(result):
    # This bounded side channel preserves observation gaps from nested MCP
    # calls. It cannot grant authority or change the business return value.
    meta = result.get("_meta")
    trace_meta = meta.get("openbkn.ai/trace") if isinstance(meta, dict) else None
    reasons = trace_meta.get("partial_reasons") if isinstance(trace_meta, dict) else None
    _record_trace_gaps(reasons)

def _observe_trace_gap_content(text):
    if not isinstance(text, str) or not text.startswith(_TRACE_DIAGNOSTIC_PREFIX):
        return False
    try:
        value = json.loads(text[len(_TRACE_DIAGNOSTIC_PREFIX):])
    except (TypeError, json.JSONDecodeError):
        return False
    if not isinstance(value, dict) or set(value) != {"bkn_trace"}:
        return False
    trace = value.get("bkn_trace")
    if not isinstance(trace, dict):
        return False
    _record_trace_gaps(trace.get("partial_reasons"))
    return True

def _record_trace_gaps(reasons):
    if not isinstance(reasons, list):
        return
    for reason in reasons[:64]:
        if len(_TRACE_GAPS) >= 64:
            return
        if not isinstance(reason, str) or len(reason) > 256 or not _TRACE_GAP_REASON.fullmatch(reason) or reason in _TRACE_GAPS:
            continue
        _TRACE_GAPS.add(reason)
        warning = json.dumps({"partial_reason": reason}, ensure_ascii=True, separators=(",", ":"))
        sys.stderr.write("\n[BKN_TRACE_GAP]" + warning + "\n")


def _call(tool, args):
    """Call an MCP tool, omitting None so the server applies schema defaults."""
    _ensure_session()
    payload = {k: v for k, v in args.items() if v is not None}
    # A successful lifecycle start supplies managed context implicitly. An
    # unavailable start leaves this empty and business remains callable.
    if _CFG.get("bkn"):
        payload["bkn_context"] = _CFG["bkn"]

    result = _rpc("tools/call", {"name": tool, "arguments": payload})["result"]
    _observe_trace_gaps(result)
    text_parts = []
    for content in result["content"]:
        if content["type"] != "text":
            continue
        if _observe_trace_gap_content(content.get("text", "")):
            continue
        text_parts.append(content["text"])
    text = "".join(text_parts)
    if result.get("isError") or result.get("is_error"):
        raise ToolError(tool + ": " + text)
    try:
        value = json.loads(text)
    except json.JSONDecodeError:
        # Return non-JSON representations, such as response_format=toon, unchanged.
        return text
    _remember_shape(tool, value)
    return value


def _describe(value, depth=0):
    """把一个值压成形状描述。只留键名与条数，不留值。

    深到 3 层：顶层 dict -> 数组 -> 元素 dict 的键名。字段名多半就在最后那层
    （nodes[].object_type_name、object_types[].concept_name），折在前面就白记了。
    """
    if isinstance(value, dict):
        if depth >= 3:
            return "{%d 键}" % len(value)
        inner = ", ".join(
            "%s: %s" % (k, _describe(v, depth + 1)) for k, v in list(value.items())[:12]
        )
        more = ", …共 %d 键" % len(value) if len(value) > 12 else ""
        return "{" + inner + more + "}"
    if isinstance(value, list):
        if not value:
            return "[]"
        return "[%d × %s]" % (len(value), _describe(value[0], depth + 1))
    return type(value).__name__


def _remember_shape(tool, value):
    _SHAPES.append((tool, _describe(value)))
    del _SHAPES[:-_SHAPE_LIMIT]


def _shape_report():
    """给失败的执行附上最近几次调用的返回结构。"""
    if not _SHAPES:
        return ""
    lines = ["", "[最近的返回结构——按这个改，不必再跑一轮把数据打出来找字段名]"]
    lines += ["  %s -> %s" % (tool, shape) for tool, shape in _SHAPES]
    return "\n".join(lines)


def _install_shape_hook():
    """让脚本失败时带上最近几次调用的返回结构。

    要挂两处，因为沙箱的两套 wrapper 对异常的处理不一样：

      - subprocess runner 直接 `result = handler(event)`，异常未捕获，走 excepthook；
      - bwrap runner 把它包在 try/except 里，打完 traceback 后 sys.exit(1)，
        excepthook 永远不会被调用。

    只挂 excepthook 的话，这段在开了 bwrap 的部署上完全不生效——而那是生产配置。
    所以同时接管 sys.exit：非零退出即视为失败。

    装在 stub 而不是 wrapper 里：wrapper 有三处实现（服务端 /mcp/ptc、studio、
    沙箱 SDK），且改 wrapper 等于让沙箱运行时去认识 BKN 的东西。
    """
    if getattr(sys, "_bkn_shape_hook", False):
        return

    def emit():
        report = _shape_report()
        if report:
            sys.stderr.write(report + "\n")

    previous_hook = sys.excepthook

    def hook(kind, value, tb):
        previous_hook(kind, value, tb)
        emit()

    previous_exit = sys.exit

    def guarded_exit(code=0):
        # 只在失败时补报告：成功退出时它是噪音，而 stderr 会原样回到调用方。
        if code:
            emit()
        previous_exit(code)

    sys.excepthook = hook
    sys.exit = guarded_exit
    sys._bkn_shape_hook = True
